using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEngine;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.StudentLife;using Rootborn.UI.StudentLife;
namespace Rootborn.Tests.EditMode.UI.StudentLife{
public sealed class CareerPracticeResultVocabularyTests{
[TestCase("ko")][TestCase("en")]public void AuthoredCareerPracticeStats_HavePlayerFacingLabels(string language){var catalog=AssetDatabase.LoadAssetAtPath<GameTextCatalog>("Assets/Localization/GameTextCatalog.asset");var paths=new[]{"Assets/Data/StudentLife/CareerPractices/Traits","Assets/Data/StudentLife/CareerPractices/Skills"};var missing=AssetDatabase.FindAssets("t:ScriptableObject",paths).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadMainAssetAtPath).Select(x=>new SerializedObject(x).FindProperty("_displayNameKey")?.stringValue).Where(x=>!string.IsNullOrEmpty(x)&&catalog.Get(x,language)==x).ToArray();Assert.That(missing,Is.Empty,language+" missing career stat labels: "+string.Join(",",missing));}
[Test]public void PracticeAndCandidateResultLines_AreReadableInKorean(){var registry=AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset");string previous=GameText.Language;var go=new GameObject("CareerResultVocabulary");try{GameDataRegistryProvider.SetOverrideForTests(registry);GameText.Language="ko";var panel=go.AddComponent<StudentDayResultPanel>();panel.Show(null,new StudentDaySummary(6,new string[0],new[]{"practice.chef:+trait.focus=2","practice.chef:+skill.cooking=3","candidate.chef:hint.chef.practice:ReadyForChoice"},string.Empty));string text=panel.ResultsTextForTests;Assert.That(text,Does.Contain("집중력"));Assert.That(text,Does.Contain("요리"));Assert.That(text,Does.Contain("진로 선택 가능"));Assert.That(text,Does.Not.Contain("trait.focus").And.Not.Contain("skill.cooking").And.Not.Contain("ReadyForChoice"));}finally{Object.DestroyImmediate(go);GameText.Language=previous;GameDataRegistryProvider.ClearOverrideForTests();GameDataRegistryProvider.ResetCacheForTests();}}
[TestCase("ko")][TestCase("en")]public void FacilityWorkActivity_UsesAuthoredPlayerFacingName(string language){var registry=AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset");string previous=GameText.Language;var go=new GameObject("FacilityWorkResultVocabulary");try{GameDataRegistryProvider.SetOverrideForTests(registry);GameText.Language=language;var work=registry.FacilityWorks.First();var panel=go.AddComponent<StudentDayResultPanel>();panel.Show(null,new StudentDaySummary(7,new[]{work.Id},new string[0],string.Empty));Assert.That(panel.ResolveText(work.Id),Is.EqualTo(GameText.Get(work.DisplayNameKey)));Assert.That(panel.ResolveText(work.Id),Is.Not.EqualTo(work.Id));}finally{Object.DestroyImmediate(go);GameText.Language=previous;GameDataRegistryProvider.ClearOverrideForTests();GameDataRegistryProvider.ResetCacheForTests();}}
}}
